"},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"Here's the result of running `cat -n` on server-adb-shell/socket_client.sh:
 1	#!/bin/bash
 2	
 3	# Socket客户端脚本
 4	# 用于向截图服务发送命令
 5	
 6	set -e
 7	
 8	# 配置
 9	DEVICE_PATH="/data/local/tmp"
 10	SERVICE_DEX="k-server.dex"
 11	TEST_CLASS="com.github.kirer.adb.test.SocketClient"
 12	SOCKET_PORT=8888
 13	
 14	# 颜色输出
 15	GREEN='\033[0;32m'
 16	RED='\033[0;31m'
 17	YELLOW='\033[1;33m'
 18	NC='\033[0m'
 19	
 20	log_info() {
 21	 echo -e "${GREEN}[INFO]${NC} $1"
 22	}
 23	
 24	log_error() {
 25	 echo -e "${RED}[ERROR]${NC} $1"
 26	}
 27	
 28	log_warn() {
 29	 echo -e "${YELLOW}[WARN]${NC} $1"
 30	}
 31	
 32	# 检查设备连接
 33	check_device() {
 34	 if ! adb devices | grep -q "device$"; then
 35	 log_error "没有检测到Android设备连接"
 36	 exit 1
 37	 fi
 38	}
 39	
 40	# 发送命令
 41	send_command() {
 42	 local command="$1"
 43	 if [ -z "$command" ]; then
 44	 log_error "命令不能为空"
 45	 return 1
 46	 fi
 47	
 48	 log_info "发送命令: $command"
 49	
 50	 # 检查DEX文件是否存在
 51	 if ! adb shell "test -f $DEVICE_PATH/$SERVICE_DEX" 2>/dev/null; then
 52	 log_error "DEX文件不存在: $DEVICE_PATH/$SERVICE_DEX"
 53	 log_info "请先运行部署脚本: ./server-adb-shell/deploy.sh"
 54	 return 1
 55	 fi
 56	
 57	 # 使用Java客户端发送命令
 58	 local response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $TEST_CLASS localhost $SOCKET_PORT '$command'" 2>/dev/null || echo "ERROR")
 59	
 60	 if [[ "$response" == *"ERROR"* ]] || [ -z "$response" ]; then
 61	 log_error "命令执行失败或服务未响应"
 62	 log_info "请检查服务是否正在运行: ./server-adb-shell/deploy.sh --test"
 63	 return 1
 64	 else
 65	 log_info "服务响应:"
 66	 echo "$response"
 67	 return 0
 68	 fi
 69	}
 70	
 71	# 显示使用说明
 72	show_usage() {
 73	 echo "Screenshot Service Socket 客户端"
 74	 echo ""
 75	 echo "用法:"
 76	 echo " $0 <command> # 发送命令到服务"
 77	 echo " $0 --port 9999 <cmd> # 使用自定义端口"
 78	 echo " $0 --help # 显示帮助"
 79	 echo ""
 80	 echo "可用命令:"
 81	 echo " screenshot <path> # 截图并保存到指定路径"
 82	 echo " status # 获取服务状态"
 83	 echo " help # 显示服务端帮助"
 84	 echo ""
 85	 echo "示例:"
 86	 echo " $0 'screenshot /sdcard/test.png'"
 87	 echo " $0 'status'"
 88	 echo " $0 --port 9999 'status'"
 89	 echo ""
 90	}
 91	
 92	# 主函数
 93	main() {
 94	 local command=""
 95	
 96	 # 解析参数
 97	 while [[ $# -gt 0 ]]; do
 98	 case $1 in
 99	 --port)
 100	 SOCKET_PORT="$2"
 101	 shift 2
 102	 ;;
 103	 --help)
 104	 show_usage
 105	 exit 0
 106	 ;;
 107	 *)
 108	 if [ -z "$command" ]; then
 109	 command="$1"
 110	 else
 111	 log_warn "忽略额外参数: $1"
 112	 fi
 113	 shift
 114	 ;;
 115	 esac
 116	 done
 117	
 118	 if [ -z "$command" ]; then
 119	 show_usage
 120	 exit 1
 121	 fi
 122	
 123	 log_info "=== Screenshot Service Socket 客户端 ==="
 124	
 125	 # 检查设备连接
 126	 check_device
 127	
 128	 # 发送命令
 129	 send_command "$command"
 130	}
 131	
 132	# 执行主函数
 133	main "$@"
 134	
