) {\n bitmap.recycle();\n }\n }\n }", "old_str_start_line_number": 93, "old_str_end_line_number": 136, "new_str": " /**\n * \u4fdd\u5b58\u622a\u56fe\u5230\u6587\u4ef6\uff08\u7528\u4e8e\u6d4b\u8bd5\u548c\u8c03\u8bd5\uff09\n */\n public void saveScreenshot(String filePath) throws Exception {\n boolean success = saveScreenshotSafe(filePath);\n if (!success) {\n throw new RuntimeException(\"Failed to capture or save screenshot\");\n }\n }\n \n /**\n * \u5b89\u5168\u5730\u4fdd\u5b58\u622a\u56fe\u5230\u6587\u4ef6\uff0c\u5931\u8d25\u65f6\u8fd4\u56defalse\u800c\u4e0d\u629b\u51fa\u5f02\u5e38\n */\n public boolean saveScreenshotSafe(String filePath) {\n Bitmap bitmap = takeScreenshot();\n if (bitmap == null) {\n Ln.e(\"Failed to capture screenshot - no image available\");\n return false;\n }\n \n try {\n File file = new File(filePath);\n File parentDir = file.getParentFile();\n if (parentDir != null && !parentDir.exists()) {\n boolean created = parentDir.mkdirs();\n if (!created && !parentDir.exists()) {\n Ln.e(\"Failed to create directory: \" + parentDir.getAbsolutePath());\n return false;\n }\n }\n \n FileOutputStream fos = new FileOutputStream(file);\n boolean compressed = bitmap.compress(Bitmap.CompressFormat.PNG, 100, fos);\n fos.close();\n \n if (!compressed) {\n Ln.e(\"Failed to compress bitmap to PNG format\");\n return false;\n }\n \n // \u9a8c\u8bc1\u6587\u4ef6\u662f\u5426\u6210\u529f\u521b\u5efa\n if (!file.exists() || file.length() == 0) {\n Ln.e(\"Screenshot file was not created or is empty\");\n return false;\n }\n \n Ln.i(\"Screenshot saved to: \" + filePath + \" (size: \" + file.length() + \" bytes)\");\n return true;\n \n } catch (IOException e) {\n Ln.e(\"Failed to save screenshot to \" + filePath, e);\n return false;\n } finally {\n // \u56de\u6536Bitmap\n if (bitmap != null && !bitmap.isRecycled()) {\n bitmap.recycle();\n }\n }\n }"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"现在我需要在 `ScreenshotService` 中添加一个 `saveScreenshotSafe`