t\u670d\u52a1\"\n echo \" $0 --direct <cmd> # \u6267\u884c\u76f4\u63a5\u547d\u4ee4\"\n echo \" $0 --socket-cmd <cmd> # \u53d1\u9001Socket\u547d\u4ee4\"\n echo \"\"\n echo \"\u6a21\u5f0f\u8bf4\u660e:\"\n echo \" Socket\u6a21\u5f0f (\u9ed8\u8ba4) \u542f\u52a8\u6301\u7eed\u7684Socket\u670d\u52a1\"\n echo \" \u76f4\u63a5\u6a21\u5f0f \u6267\u884c\u5355\u4e2a\u547d\u4ee4\u540e\u9000\u51fa\"\n echo \" Socket\u5ba2\u6237\u7aef \u5411\u8fd0\u884c\u4e2d\u7684Socket\u670d\u52a1\u53d1\u9001\u547d\u4ee4\"\n echo \"\"\n echo \"\u76f4\u63a5\u547d\u4ee4\u793a\u4f8b:\"\n echo \" $0 --direct 'status'\"\n echo \" $0 --direct 'screenshot /sdcard/test.png'\"\n echo \"\"\n echo \"Socket\u547d\u4ee4\u793a\u4f8b:\"\n echo \" $0 --socket-cmd 'status'\"\n echo \" $0 --socket-cmd 'screenshot /sdcard/test.png'\"\n echo \" $0 --port 9999 --socket-cmd 'status' # \u4f7f\u7528\u81ea\u5b9a\u4e49\u7aef\u53e3\"\n echo \"\"\n}", "old_str_start_line_number": 150, "old_str_end_line_number": 178, "new_str": "# \u663e\u793a\u4f7f\u7528\u8bf4\u660e\nshow_usage() {\n echo \"KServer \u5feb\u901f\u90e8\u7f72\u811a\u672c\"\n echo \"\"\n echo \"\u7528\u6cd5:\"\n echo \" $0 -d # \u76f4\u63a5\u6a21\u5f0f\u90e8\u7f72\"\n echo \" $0 -d --screenshot # \u76f4\u63a5\u6a21\u5f0f\u90e8\u7f72\u5e76\u83b7\u53d6bitmap\uff08\u6253\u5370\u8017\u65f6\uff09\"\n echo \" $0 -d --screenshot <path> # \u76f4\u63a5\u6a21\u5f0f\u90e8\u7f72\u5e76\u622a\u56fe\u5230\u8def\u5f84\uff08\u5206\u522b\u6253\u5370bitmap\u548c\u4fdd\u5b58\u8017\u65f6\uff09\"\n echo \" $0 -s # Socket\u6a21\u5f0f\u90e8\u7f72\"\n echo \" $0 -s --port 8888 # Socket\u6a21\u5f0f\u90e8\u7f72\u6307\u5b9a\u7aef\u53e3\"\n echo \" $0 -s -t --screenshot # Socket\u6a21\u5f0f\u6d4b\u8bd5\u83b7\u53d6bitmap\uff08\u6253\u5370\u8017\u65f6\uff09\"\n echo \" $0 -s -t --screenshot <path> # Socket\u6a21\u5f0f\u6d4b\u8bd5\u622a\u56fe\u5230\u8def\u5f84\uff08\u5206\u522b\u6253\u5370bitmap\u548c\u4fdd\u5b58\u8017\u65f6\uff09\"\n echo \"\"\n echo \"\u5176\u4ed6\u9009\u9879:\"\n echo \" -