 10	public class ScreenshotCommand implements ServiceCommand {
 11	 
 12	 private final ScreenshotService screenshotService;
 13	 
 14	 public ScreenshotCommand(ScreenshotService screenshotService) {
 15	 this.screenshotService = screenshotService;
 16	 }
 17	 
 18	 @Override
 19	 public String execute(String[] params) {
 20	 try {
 21	 if (params.length == 0) {
 22	 return "ERROR Missing output path. Usage: screenshot <output_path>";
 23	 }
 24	
 25	 String outputPath = params[0];
 26	
 27	 // 验证路径
 28	 if (outputPath.trim().isEmpty()) {
 29	 return "ERROR Invalid output path";
 30	 }
 31	
 32	 // 检查服务状态
 33	 if (!screenshotService.isRunning()) {
 34	 return "ERROR Screenshot service is not running";
 35	 }
 36	
 37	 // 执行截图
 38	 boolean success = screenshotService.saveScreenshotSafe(outputPath);
 39	
 40	 if (success) {
 41	 return "OK Screenshot saved to " + outputPath;
 42	 } else {
 43	 return "ERROR Failed to capture or save screenshot";
 44	 }
 45	
 46	 } catch (Exception e) {
 47	 Ln.e("Error executing screenshot command", e);
 48	 return "ERROR " + e.getMessage();
 49	 }
 50	 }
 51	 
