u7406\u5b57\u8282\u6570\u7ec4\u54cd\u5e94\uff0c\u53d1\u9001\u4e8c\u8fdb\u5236\u6570\u636e\n */\n private void handleBytesResponse(java.io.OutputStream out, CommandResult result) throws IOException {\n byte[] imageBytes = (byte[]) result.getData();\n if (imageBytes != null) {\n try {\n // \u53d1\u9001\u534f\u8bae\u5934\uff1a\u6d88\u606f\u7c7b\u578b + \u6570\u636e\u957f\u5ea6 + \u6d88\u606f\n String header = \"BYTES:\" + imageBytes.length + \":\" + result.getMessage() + \"\\n\";\n out.write(header.getBytes(\"UTF-8\"));\n \n // \u53d1\u9001\u4e8c\u8fdb\u5236\u6570\u636e\n out.write(imageBytes);\n out.flush();\n \n Ln.d(\"Sent bytes response: \" + imageBytes.length + \" bytes\");\n \n } catch (Exception e) {\n Ln.e(\"Failed to send bytes\", e);\n String errorResponse = \"ERROR Failed to send bytes: \" + e.getMessage() + \"\\n\";\n out.write(errorResponse.getBytes(\"UTF-8\"));\n out.flush();\n }\n } else {\n String errorResponse = \"ERROR Bytes data is null\\n\";\n out.write(errorResponse.getBytes(\"UTF-8\"));\n out.flush();\n }\n }"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":""},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"unseen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"Successfully edited the file server-adb-shell/src/main/java/com/github/kirer/adb/net/SocketServer.java.
