urn existing;\n }\n\n // \u521b\u5efa\u7b49\u5f85\u9501\n imageLatch = new CountDownLatch(1);\n Ln.d(\"Created new CountDownLatch, waiting for image...\");\n\n // \u7b49\u5f85\u56fe\u50cf\u53ef\u7528\n boolean received = imageLatch.await(timeoutMs, java.util.concurrent.TimeUnit.MILLISECONDS);\n Ln.d(\"Wait result: \" + received);\n\n if (received) {\n Image image = latestImage.get();\n if (image != null) {\n Ln.d(\"Image received after waiting: \" + image.getWidth() + \"x\" + image.getHeight());\n return image;\n } else {\n Ln.w(\"Image latch signaled but no image available\");\n return null;\n }\n } else {\n Ln.w(\"Timeout waiting for image after \" + timeoutMs + \"ms\");\n return null;\n }\n } catch (InterruptedException e) {\n Ln.w(\"Interrupted while waiting for image\", e);\n Thread.currentThread().interrupt();\n return null;\n } catch (Exception e) {\n Ln.e(\"Exception in waitForImage()\", e);\n return null;\n } finally {\n imageLatch = null;\n Ln.i(\"=== waitForImage() finished ===\");\n }\n }"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"在 `ImageReaderHandler.waitForImage` 中添加日志：
