 1	package com.github.kirer.adb
 2	
 3	import android.os.Looper
 4	import com.genymobile.scrcpy.util.Ln
 5	import com.github.kirer.adb.commands.ScreenshotCommand
 6	import com.github.kirer.adb.net.CommandProcessor
 7	import com.github.kirer.adb.net.CommandResult
 8	import com.github.kirer.adb.net.SocketServer
 9	import com.github.kirer.adb.screenshot.ScreenshotConfig
 10	import com.github.kirer.adb.screenshot.ScreenshotService
 11	
 12	object Launcher {
 13	 private const val VERSION = "1.0.0"
 14	 private var socketPort = 8888
 15	 private var screenshotService: ScreenshotService? = null
 16	 private var socketMode = false
 17	 private var directCommand: String? = null
 18	
 19	 /**
 20	 * 主入口点，通过app_process调用
 21	 */
 22	 @JvmStatic
 23	 fun main(args: Array<String>) {
 24	 Ln.i("K Shell ADB Service v" + VERSION + " starting...")
 25	 // 设置未捕获异常处理器
 26	 Thread.setDefaultUncaughtExceptionHandler(Thread.UncaughtExceptionHandler { thread: Thread?, exception: Throwable? ->
 27	 Ln.e("Uncaught exception in thread " + thread!!.getName(), exception)
 28	 System.exit(1)
 29	 })
 30	 try {
 31	 // 解析命令行参数
 32	 val config = parseArguments(args)
 33	 if (socketMode) {
 34	 // Socket服务模式：启动持续服务
 35	 // 准备主循环器
 36	 prepareMainLooper()
 37	 // 创建并初始化服务
 38	 screenshotService = ScreenshotService(config)
 39	 // 启动服务
 40	 screenshotService!!.start()
 41	 startSocketServer(screenshotService)
 42	 // 运行主循环
 43	 Looper.loop()
 44	 } else {
 45	 // 直接模式：执行命令并退出（默认模式）
 46	 // 在直接模式下，如果是无参数的screenshot命令，禁用日志输出
 47	 if (directCommand != null && directCommand!!.trim { it <= ' ' } == "screenshot") {
 48	 Ln.initLogLevel(Ln.Level.ERROR) // 只显示错误日志
 49	 }
 50	 executeDirectCommand(config, directCommand)
 51	 }
 52	 } catch (e: Exception) {
 53	 Ln.e("Fatal error during startup", e)
 54	 System.exit(1)
 55	 } finally {
 56	 if (screenshotService != null) {
 57	 screenshotService!!.cleanup()
 58	 }
 59	 }
 60	 }
 61	
 62	 /**
 63	 * 准备主循环器
 64	 */
 65	 private fun prepareMainLooper() {
 66	 if (Looper.myLooper() == null) {
 67	 Looper.prepare()
 68	 }
 69	 }
 70	
 71	 /**
 72	 * 解析命令行参数
 73	 */
 74	 private fun parseArguments(args: Array<String>): ScreenshotConfig {
 75	 val config = ScreenshotConfig()
 76	 var i = 0
 77	 while (i < args.size) {
 78	 val arg = args[i]
 79	 try {
 80	 when (arg) {
 81	 "--help", "-h" -> {
 82	 printUsage()
 83	 System.exit(0)
 84	 }
 85	
 86	 "--version", "-v" -> {
 87	 println("Screenshot Service v" + VERSION)
 88	 System.exit(0)
 89	 }
 90	
 91	 "--debug" -> Ln.initLogLevel(Ln.Level.DEBUG)
 92	 "--port", "-p" -> if (i + 1 < args.size && !args[i + 1].startsWith("-")) {
 93	 socketPort = args[++i].toInt()
 94	 }
 95	
 96	 "--display-id", "-d" -> if (i + 1 < args.size) {
 97	 config.setDisplayId(args[++i].toInt())
 98	 }
 99	
 100	 "--max-images", "-m" -> if (i + 1 < args.size) {
 101	 config.setMaxImages(args[++i].toInt())
 102	 }
 103	
 104	 "--no-auto-rotate" -> config.setAutoRotate(false)
 105	 "--socket", "-s" -> socketMode = true
 106	 else -> if (arg.startsWith("-")) {
 107	 Ln.w("Unknown argument: " + arg)
 108	 } else {
 109	 // 非选项参数作为直接命令
 110	 if (directCommand == null) {
 111	 directCommand = arg
 112	 } else {
 113	 directCommand += " " + arg
 114	 }
 115	 }
 116	 }
 117	 } catch (e: NumberFormatException) {
 118	 Ln.e("Invalid number format for argument " + arg)
 119	 System.exit(1)
 120	 }
 121	 i++
 122	 }
 123	
 124	 Ln.i("Using config: " + config)
 125	 if (socketMode) {
 126	 Ln.i("Socket mode enabled on port: " + socketPort)
 127	 } else {
 128	 Ln.i("Direct mode enabled with command: " + (if (directCommand != null) directCommand else "none"))
 129	 }
 130	
 131	 return config
 132	 }
 133	
 134	 /**
 135	 * 打印使用说明
 136	 */
 137	 private fun printUsage() {
 138	 println("K Shell ADB Service v" + VERSION)
 139	 println("Usage: CLASSPATH=k-server.dex app_process /system/bin com.github.kirer.adb.Launcher [options] [command]")
 140	 println()
 141	 println("Modes:")
 142	 println(" Direct Mode (default) Execute command and exit")
 143	 println(" Socket Mode (-s/--socket) Start persistent socket server")
 144	 println()
 145	 println("Options:")
 146	 println(" -d, --display-id <id> Display ID to capture (default: 0)")
 147	 println(" -m, --max-images <num> Maximum images in buffer (default: 2)")
 148	 println(" -s, --socket Enable socket server mode")
 149	 println(" -p, --port <port> Socket server port (default: 8888)")
 150	 println(" --no-auto-rotate Disable automatic rotation handling")
 151	 println(" --debug Enable debug logging")
 152	 println(" -h, --help Show this help message")
 153	 println(" -v, --version Show version information")
 154	 println()
 155	 println("Direct Mode Examples:")
 156	 println(" # Take screenshot directly")
 157	 println(" adb shell CLASSPATH=/data/local/tmp/k-server.dex app_process /system/bin com.github.kirer.adb.Launcher screenshot /sdcard/test.png")
 158	 println()
 159	 println(" # Get status")
 160	 println(" adb shell CLASSPATH=/data/local/tmp/k-server.dex app_process /system/bin com.github.kirer.adb.Launcher status")
 161	 println()
 162	 println("Socket Mode Examples:")
 163	 println(" # Start socket server on default port 8888")
 164	 println(" adb shell CLASSPATH=/data/local/tmp/k-server.dex app_process /system/bin com.github.kirer.adb.Launcher --socket")
 165	 println()
 166	 println(" # Start socket server on custom port")
 167	 println(" adb shell CLASSPATH=/data/local/tmp/k-server.dex app_process /system/bin com.github.kirer.adb.Launcher --socket --port 9999")
 168	 println()
 169	 println("Available Commands:")
 170	 println(" screenshot <path> Take screenshot and save to path")
 171	 println(" status Get service status")
 172	 println(" help Show available commands")
 173	 }
 174	
 175	 private fun startSocketServer(screenshotService: ScreenshotService?) {
 176	 try {
 177	 // 创建命令处理器
 178	 val commandProcessor = CommandProcessor()
 179	 // 注册命令
 180	 commandProcessor.registerCommand(ScreenshotCommand(screenshotService))
 181	 // 创建并启动Socket服务器
 182	 val socketServer = SocketServer(socketPort, commandProcessor)
 183	 socketServer.start()
 184	 Ln.i("Socket server started on port " + socketPort)
 185	 } catch (e: Exception) {
 186	 Ln.e("Failed to start socket server", e)
 187	 throw RuntimeException("Socket server start failed", e)
 188	 }
 189	 }
 190	
 191	 /**
 192	 * 执行直接命令模式
 193	 */
 194	 private fun executeDirectCommand(config: ScreenshotConfig?, command: String?) {
 195	 try {
 196	 // 创建并初始化服务
 197	 screenshotService = ScreenshotService(config)
 198	 screenshotService!!.start()
 199	
 200	 // 创建命令处理器
 201	 val commandProcessor = CommandProcessor()
 202	 commandProcessor.registerCommand(ScreenshotCommand(screenshotService))
 203	
 204	 // 处理命令
 205	 val result: CommandResult
 206	 if (command == null || command.trim { it <= ' ' }.isEmpty()) {
 207	 // 如果没有提供命令，显示状态信息
 208	 result =
 209	 CommandResult.success("Service initialized successfully. Available commands: screenshot [path], status, help")
 210	 } else {
 211	 // 执行指定的命令
 212	 result = commandProcessor.execute(command.trim { it <= ' ' })
 213	 }
 214	
 215	 // 处理结果
 216	 if (result.getType() == CommandResult.Type.BYTES) {
 217	 // 如果是字节数组结果，直接输出字节数组
 218	 val imageBytes = result.getData() as ByteArray?
 219	 if (imageBytes != null) {
 220	 try {
 221	 // 直接将字节数组写入stdout，不输出任何文本
 222	 System.out.write(imageBytes)
 223	 System.out.flush()
 224	
 225	 // 不输出任何文本信息，直接退出
 226	 System.exit(0)
 227	 } catch (e: Exception) {
 228	 System.exit(1)
 229	 }
 230	 } else {
 231	 System.exit(1)
 232	 }
 233	 } else if (result.getType() == CommandResult.Type.BOOLEAN) {
 234	 // 如果是布尔结果，输出true/false
 235	 val success = result.getData() as Boolean
 236	 println(if (success) "OK " + result.getMessage() else "ERROR " + result.getMessage())
 237	 System.exit(if (success) 0 else 1)
 238	 } else {
 239	 // 普通字符串结果
 240	 println(result.toStringResponse())
 241	 }
 242	
 243	 // 根据结果设置退出码
 244	 if (!result.isSuccess()) {
 245	 System.exit(1)
 246	 } else {
 247	 System.exit(0)
 248	 }
 249	 } catch (e: Exception) {
 250	 Ln.e("Error in direct command execution", e)
 251	 System.err.println("ERROR " + e.message)
 252	 System.exit(1)
 253	 }
 254	 }
 255	}
