 52	 private CommandResult getBitmapResult() {
 53	 long startTime = System.currentTimeMillis();
 54	
 55	 // 直接获取PNG字节数组
 56	 byte[] pngBytes = screenshotService.takePngBytes();
 57	
 58	 long duration = System.currentTimeMillis() - startTime;
 59	
 60	 if (pngBytes != null) {
 61	 String message = "PNG bytes captured in " + duration + "ms, bytes: " + pngBytes.length;
 62	 return CommandResult.bytes(pngBytes, message);
 63	 } else {
 64	 return CommandResult.error("Failed to capture PNG bytes after " + duration + "ms");
 65	 }
