 19	 public String execute(String[] params) {
 20	 try {
 21	 if (params.length == 0) {
 22	 return "ERROR Missing output path. Usage: screenshot <output_path>";
 23	 }
 24	 
 25	 String outputPath = params[0];
 26	 
 27	 // 验证路径
 28	 if (outputPath.trim().isEmpty()) {
 29	 return "ERROR Invalid output path";
 30	 }
 31	 
 32	 // 执行截图
 33	 screenshotService.saveScreenshot(outputPath);
 34	 
 35	 return "OK Screenshot saved to " + outputPath;
 36	 
 37	 } catch (Exception e) {
 38	 Ln.e("Error executing screenshot command", e);
 39	 return "ERROR " + e.getMessage();
 40	 }
 41	 }
