 128	 ByteBuffer buffer = image.getPlanes()[0].getBuffer();
 129	 byte[] bytes = new byte[buffer.remaining()];
 130	 buffer.get(bytes);
 131	
 132	 return android.graphics.BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
