 135	 /**
 136	 * 转换RGBA8888格式的图像
 137	 */
 138	 private static Bitmap convertRGBA8888ToBitmap(Image image) {
 139	 if (image.getFormat() != PixelFormat.RGBA_8888) {
 140	 throw new IllegalArgumentException("Unsupported format, expected RGBA_8888");
 141	 }
 142	 Image.Plane[] planes = image.getPlanes();
 143	 ByteBuffer buffer = planes[0].getBuffer();
 144	 int pixelStride = planes[0].getPixelStride(); // 通常为4
 145	 int rowStride = planes[0].getRowStride(); // 可能大于 width * 4
 146	 int rowPadding = rowStride - pixelStride * image.getWidth();
 147	 int width = image.getWidth();
 148	 int height = image.getHeight();
 149	 // 创建比实际内容宽的 Bitmap，包含 row padding
 150	 Bitmap bitmap = Bitmap.createBitmap(
 151	 rowStride / pixelStride, // padded width
 152	 height,
 153	 Bitmap.Config.ARGB_8888
 154	 );
 155	 bitmap.copyPixelsFromBuffer(buffer);
 156	 // 剪裁去掉 padding，返回最终 Bitmap
 157	 return Bitmap.createBitmap(bitmap, 0, 0, width, height);
 158	 }
