 171	 yuvImage.compressToJpeg(new android.graphics.Rect(0, 0, width, height), 100, out);
 172	 byte[] jpegBytes = out.toByteArray();
 173	
 174	 // 解码JPEG为Bitmap
 175	 return android.graphics.BitmapFactory.decodeByteArray(jpegBytes, 0, jpegBytes.length);
