 3	import java.io.BufferedReader;
 4	import java.io.InputStreamReader;
 5	import java.io.PrintWriter;
 6	import java.net.Socket;
 7	
 8	/**
 9	 * 简单的Socket客户端，用于测试截图服务
 10	 */
 11	public class SocketClient {
 12	 
 13	 public static void main(String[] args) {
 14	 if (args.length < 2) {
 15	 System.out.println("Usage: SocketClient <host> <port> [command]");
 16	 System.out.println("Example: SocketClient localhost 8888 status");
 17	 return;
 18	 }
 19	 
 20	 String host = args[0];
 21	 int port = Integer.parseInt(args[1]);
 22	 String command = args.length > 2 ? args[2] : "status";
 23	 
 24	 try {
 25	 Socket socket = new Socket(host, port);
 26	 
 27	 PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
 28	 BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
 29	 
 30	 // 发送命令
 31	 out.println(command);
 32	 
 33	 // 读取响应
 34	 String response = in.readLine();
 35	 System.out.println("Response: " + response);
 36	 
 37	 socket.close();
 38	 
 39	 } catch (Exception e) {
 40	 System.err.println("Error: " + e.getMessage());
 41	 }
 42	 }
 43	}
 44	
